import itertools

solutions = []
# x[i] is count of i in the sequence. Sum x[i] = 9.
# Also x[i] must be between 0 and 9.
# We can generate all compositions of 9 into 9 parts (stars and bars) = C(17,8)=24310, manageable.
# But we also need sum(i*x[i]) = 9.

from itertools import combinations_with_replacement, permutations

# Actually generate all tuples of nonnegative ints summing to 9.
def generate_partitions(n, k):
    # generate all k-tuples of nonnegative ints summing to n
    if k == 1:
        yield (n,)
        return
    for i in range(n+1):
        for tail in generate_partitions(n-i, k-1):
            yield (i,) + tail

for x in generate_partitions(9, 9):
    if sum(i * xi for i, xi in enumerate(x)) != 9:
        continue
    # check self-descriptive: for each i, x[i] == count of i in x
    # x is a tuple of length 9
    ok = True
    for i in range(9):
        if x[i] != x.count(i):
            ok = False
            break
    if ok:
        solutions.append(x)

solutions
